    catalog_json = json.dumps(catalog, separators=(",", ":"), ensure_ascii=False).replace("</", "<\\/")
    dimension_headers = "".join(f"<th>{html.escape(dimension)}</th>" for dimension in manifest["dimensions"])
    return f"""<!doctype html>
